# Generated by forge. Shared helpers for hook scripts. POSIX sh only.
FORGE_AST_GREP_VERSION="@@AST_GREP_VERSION@@"

# json_get <key> [raw]: prints the string value of a top-level or tool_input key from the
# JSON in $FORGE_INPUT (forge_json). With "raw", the value stays JSON-escaped.
json_get() {
  forge_json "$1" "${2:-}"
  printf '%s' "$FORGE_J"
}

# forge_json <key> [raw]: FORGE_J, the string value of the first "<key>": "…" of
# $FORGE_INPUT. A value without an escape (paths, ids, names: almost every value a hook
# reads) is cut out with shell builtins; one with escapes is decoded by forge_json_awk.
forge_json() {
  FORGE_J=''
  case $FORGE_INPUT in
    *"\"$1\":\""*) _js_v=${FORGE_INPUT#*"\"$1\":\""} ;;
    *"\"$1\": \""*) _js_v=${FORGE_INPUT#*"\"$1\": \""} ;;
    *"\"$1\""*) FORGE_J=$(forge_json_awk "$@"); return 0 ;;
    *) return 0 ;;
  esac
  case ${_js_v%%\"*} in
    *\\*) FORGE_J=$(forge_json_awk "$@") ;;
    *) FORGE_J=${_js_v%%\"*} ;;
  esac
  return 0
}

forge_json_awk() {
  printf '%s' "$FORGE_INPUT" | awk -v key="$1" -v raw="${2:-}" '
    { buf = buf $0 "\n" }
    END {
      if (!match(buf, "\"" key "\"[[:space:]]*:[[:space:]]*\"")) exit
      s = substr(buf, RSTART + RLENGTH); out = ""; n = length(s)
      for (i = 1; i <= n; i++) {
        c = substr(s, i, 1)
        if (c == "\"") break
        if (c == "\\") {
          i++; d = substr(s, i, 1)
          if (raw != "") { out = out c d; continue }
          if (d == "n") out = out "\n"
          else if (d == "t") out = out "\t"
          else if (d == "r") out = out ""
          else if (d == "u") {
            # \uXXXX: ASCII decoded, anything else kept escaped (UTF-8 arrives unescaped)
            h = tolower(substr(s, i + 1, 4)); v = 0
            for (k = 1; k <= 4; k++) v = v * 16 + index("0123456789abcdef", substr(h, k, 1)) - 1
            if (v > 0 && v < 128) out = out sprintf("%c", v); else out = out "\\u" h
            i += 4
          }
          else out = out d
        } else out = out c
      }
      printf "%s", out
    }'
}

# json_escape: stdin -> JSON string body (no surrounding quotes). Carriage returns
# are dropped; every other control character is escaped (\t, \n, \u00XX): one
# left raw makes the whole JSON invalid.
json_escape() {
  awk 'BEGIN {
    ORS = ""
    for (c = 1; c < 32; c++) if (c != 9 && c != 10 && c != 13) { ch = sprintf("%c", c); ctl[ch] = sprintf("\\u%04x", c); re = re ch }
    re = "[" re "]"
  }
  {
    gsub(/\\/, "\\\\"); gsub(/"/, "\\\""); gsub(/\t/, "\\t"); gsub(/\r/, "")
    if ($0 ~ re) {
      s = ""; n = length($0)
      for (i = 1; i <= n; i++) { ch = substr($0, i, 1); s = s ((ch in ctl) ? ctl[ch] : ch) }
      $0 = s
    }
    if (NR > 1) printf "\\n"
    printf "%s", $0
  }'
}

# tool <name>: prints the command that runs the project's own <name>, or nothing if absent
# (forge_tool_lookup).
tool() {
  forge_tool_lookup "$1"
  printf '%s' "$FORGE_TOOL_CMD"
}

# forge_tool_lookup <name>: FORGE_TOOL_CMD, the command that runs the project's own <name>
# ("" when absent), and FORGE_TOOL_BIN, its file. A Python tool (FORGE_PYTHON_TOOLS) not in
# .venv is the one of the project's Python environment elsewhere (forge_py_tool_lookup).
# Shell builtins only (no process) outside a workspace package.
forge_tool_lookup() {
  FORGE_TOOL_CMD=''
  FORGE_TOOL_BIN=''
  if [ -f bun.lock ] || [ -f bun.lockb ]; then
    if [ -x "node_modules/.bin/$1" ] && command -v bun >/dev/null 2>&1; then
      FORGE_TOOL_CMD="bun run --bun $1"
      FORGE_TOOL_BIN=node_modules/.bin/$1
    fi
  elif [ -f uv.lock ]; then
    if [ -x ".venv/bin/$1" ]; then FORGE_TOOL_CMD=.venv/bin/$1; FORGE_TOOL_BIN=$FORGE_TOOL_CMD; else forge_py_tool_lookup "$1"; fi
  elif [ -x "node_modules/.bin/$1" ]; then
    FORGE_TOOL_CMD=node_modules/.bin/$1
    FORGE_TOOL_BIN=$FORGE_TOOL_CMD
  elif [ -x ".venv/bin/$1" ]; then
    FORGE_TOOL_CMD=.venv/bin/$1
    FORGE_TOOL_BIN=$FORGE_TOOL_CMD
  elif [ -n "${FORGE_WS_ROOT:-}" ] && [ "$FORGE_WS_ROOT" != "$PWD" ]; then
    # in a workspace package: the root's install (hoisted by bun, npm and Yarn; uv's .venv)
    _tw=$(cd "$FORGE_WS_ROOT" && FORGE_WS_ROOT='' tool "$1")
    case $_tw in ''|bun\ *|/*) FORGE_TOOL_CMD=$_tw ;; *) FORGE_TOOL_CMD=$FORGE_WS_ROOT/$_tw ;; esac
    case $FORGE_TOOL_CMD in "bun run --bun "*) FORGE_TOOL_BIN=$FORGE_WS_ROOT/node_modules/.bin/$1 ;; *) FORGE_TOOL_BIN=$FORGE_TOOL_CMD ;; esac
  else
    forge_py_tool_lookup "$1"
  fi
}

# The project tools that live in a Python environment (src/core/tools.ts PYTHON_TOOLS).
FORGE_PYTHON_TOOLS='@@PYTHON_TOOLS@@'

# forge_py_tool <name>: prints the project's Python tool <name> in its environment outside
# .venv (forge_py_tool_lookup).
forge_py_tool() {
  forge_py_tool_lookup "$1"
  printf '%s' "$FORGE_TOOL_CMD"
}

# forge_py_tool_lookup <name>: FORGE_TOOL_CMD (and FORGE_TOOL_BIN), the project's Python
# tool <name> in its environment outside .venv (forge_py_env): <name> in the environment's
# scripts directories, or, for python, its interpreter; "" when it is not there, or <name> is
# not a Python tool.
forge_py_tool_lookup() {
  FORGE_TOOL_CMD=''
  FORGE_TOOL_BIN=''
  case " $FORGE_PYTHON_TOOLS " in *" $1 "*) ;; *) return 0 ;; esac
  forge_py_env || return 0
  if [ "$1" = python ]; then FORGE_TOOL_CMD=$FORGE_PY; FORGE_TOOL_BIN=$FORGE_PY; return 0; fi
  _pt_ifs=$IFS
  IFS='
'
  for _pt_d in $FORGE_PY_BIN; do
    if [ -f "$_pt_d/$1" ] && [ -x "$_pt_d/$1" ]; then FORGE_TOOL_CMD=$_pt_d/$1; FORGE_TOOL_BIN=$FORGE_TOOL_CMD; break; fi
  done
  IFS=$_pt_ifs
  return 0
}

# forge_path_lookup <name>: FORGE_FOUND, the first executable <name> on PATH ("" when none);
# shell builtins only.
forge_path_lookup() {
  FORGE_FOUND=''
  _pl_ifs=$IFS
  IFS=:
  for _pl_d in $PATH; do
    if [ -n "$_pl_d" ] && [ -f "$_pl_d/$1" ] && [ -x "$_pl_d/$1" ]; then FORGE_FOUND=$_pl_d/$1; break; fi
  done
  IFS=$_pl_ifs
  case $FORGE_FOUND in /*) ;; ?*) FORGE_FOUND=$PWD/$FORGE_FOUND ;; esac
}

# forge_py_env: the project's Python environment when it is not the repository's .venv
# (which the callers look at first): FORGE_PY, its interpreter, FORGE_PY_PREFIX, its
# sys.prefix (the environment's directory), and FORGE_PY_BIN, the directories of its
# scripts (one per line). Fails when there is none. In order:
#   - an activated virtual environment ($VIRTUAL_ENV);
#   - uv's project environment ($UV_PROJECT_ENVIRONMENT); in a uv.lock project, nothing
#     else: uv installs a project nowhere else;
#   - in a poetry.lock project, the environment Poetry itself says is the project's
#     (`poetry env info -p`, forge_poetry_env), when Poetry is on PATH; none when Poetry
#     installs into the interpreter (virtualenvs.create false);
#   - the interpreter on PATH (python3, else python): the dependencies installed into
#     it (pip, Poetry with virtualenvs.create false, a Docker image) and its scripts
#     directory (not the user scripts one, ~/.local/bin, where pipx puts global tools).
# Looked up once per directory and shell; what needs a process (Poetry's answer, the
# interpreter's prefix) is a fact (forge_fact): an unchanged environment costs no process.
forge_py_env() {
  if [ "${_pe_at:-}" = "$PWD" ]; then [ -n "$FORGE_PY" ]; return; fi
  _pe_at=$PWD
  FORGE_PY=''
  FORGE_PY_PREFIX=''
  FORGE_PY_BIN=''
  for _pe_d in "${VIRTUAL_ENV:-}" "${UV_PROJECT_ENVIRONMENT:-}"; do
    [ -n "$_pe_d" ] || continue
    case $_pe_d in /*) ;; *) _pe_d=$_pe_at/$_pe_d ;; esac
    for _pe_n in python python3; do
      if [ -x "$_pe_d/bin/$_pe_n" ]; then FORGE_PY=$_pe_d/bin/$_pe_n; FORGE_PY_PREFIX=$_pe_d; FORGE_PY_BIN=$_pe_d/bin; return 0; fi
    done
  done
  [ ! -f uv.lock ] || return 1
  if [ -f poetry.lock ]; then
    forge_path_lookup poetry
    # Poetry's own settings that move its environments (the others live in the files it reads, watched)
    if [ -n "$FORGE_FOUND" ] && forge_fact poetry-env "$PWD $FORGE_FOUND ${POETRY_VIRTUALENVS_PATH-}|${POETRY_VIRTUALENVS_CREATE-}|${POETRY_VIRTUALENVS_IN_PROJECT-}|${POETRY_CACHE_DIR-}|${POETRY_CONFIG_DIR-}|${POETRY_HOME-}" forge_poetry_env "$FORGE_FOUND"; then
      case $FORGE_FACT in
        /*)
          for _pe_n in python python3; do
            if [ -x "$FORGE_FACT/bin/$_pe_n" ]; then FORGE_PY=$FORGE_FACT/bin/$_pe_n; FORGE_PY_PREFIX=$FORGE_FACT; FORGE_PY_BIN=$FORGE_FACT/bin; return 0; fi
          done ;;
      esac
    fi
  fi
  for _pe_n in python3 python; do
    forge_path_lookup "$_pe_n"
    [ -n "$FORGE_FOUND" ] || continue
    # the interpreter's own answer, until it (or the pyenv version selecting it) changes
    forge_fact python-env "$FORGE_FOUND ${PYENV_VERSION-}" forge_py_find "$FORGE_FOUND" || continue
    _pe_i=0
    FORGE_PY_BIN=''
    _pe_ifs=$IFS
    IFS='
'
    for _pe_l in $FORGE_FACT; do
      _pe_i=$((_pe_i + 1))
      case $_pe_i in
        1) FORGE_PY=$_pe_l ;;
        2) FORGE_PY_PREFIX=$_pe_l ;;
        *) FORGE_PY_BIN="${FORGE_PY_BIN:+$FORGE_PY_BIN
}$_pe_l" ;;
      esac
    done
    IFS=$_pe_ifs
    [ -n "$FORGE_PY" ] && return 0
  done
  return 1
}

# forge_poetry_env <poetry>: the environment Poetry uses for the project in this
# directory, as Poetry says (`poetry env info -p`), or "none" (no environment yet, or
# Poetry installs into the interpreter: virtualenvs.create false). Watched: the files Poetry
# reads the project's settings from (pyproject.toml, poetry.toml), the poetry executable, and
# its virtualenvs directory (`poetry config virtualenvs.path`) with its envs.toml: an
# environment created, replaced or switched there is asked for again (forge_fact). A change
# to Poetry's global config.toml alone is seen once one of those changes.
forge_poetry_env() {
  printf 'watch %s\nwatch %s\nwatch %s\n' "$PWD/pyproject.toml" "$PWD/poetry.toml" "$1"
  _pv_where=$("$1" -n config virtualenvs.path 2>/dev/null) && [ -n "$_pv_where" ] && printf 'watch %s\nwatch %s\n' "$_pv_where" "$_pv_where/envs.toml"
  _pv_env=$("$1" -n env info -p 2>/dev/null)
  case $_pv_env in /*) printf '%s\n' "$_pv_env" ;; *) printf 'none\n' ;; esac
}

# forge_py_find <python>: the interpreter, its sys.prefix, then its scripts directories;
# watched: the interpreter and .python-version (pyenv's choice).
forge_py_find() {
  printf 'watch %s\nwatch %s\n' "$1" "$PWD/.python-version"
  "$1" -c 'import sys, sysconfig
print(sys.executable)
print(sys.prefix)
print(sysconfig.get_path("scripts"))
'
}

# forge_py_sites <python>: FORGE_FACT, "version <X.Y>" and "site <dir>" per site-packages
# directory of the interpreter's environment, in import order (what ty reads: the user site
# and PYTHONPATH left out); kept until the interpreter changes.
forge_py_sites() {
  forge_fact python-sites "$1" forge_py_sites_ask "$1"
}
forge_py_sites_ask() {
  printf 'watch %s\n' "$1"
  "$1" -I -c 'import os, sys
print("version %d.%d" % sys.version_info[:2])
seen = set()
for p in sys.path:
    if os.path.basename(p) in ("site-packages", "dist-packages") and os.path.isdir(p) and p not in seen:
        seen.add(p)
        print("site " + p)
'
}

# ---- facts: what a tool or environment says about itself, asked once and kept in the
# state (<state>/facts/, outside the repository) until what it depends on changes.

# forge_fact <name> <key> <command> [args]: sets FORGE_FACT to the value lines <command>
# prints, kept for <key>. <command> also prints "watch <path>" lines, the files and
# directories its answer depends on: the answer is reused while all of them are older than
# it (a directory changes when an entry was added, removed or renamed: a package installed
# or upgraded; one modified in the same clock tick as the answer counts as changed) and none
# that did not exist appeared. Reusing it costs no process: the record
# is found and read, and the paths compared (test -nt, -e), with shell builtins. A failing
# command is not kept, nor an answer about a path modified while it was computed (asked
# again next time). Without a state directory (outside a git repository), the command runs
# every time.
forge_fact() {
  _ff_name=$1
  # the key on one line (the index and the record are read line by line)
  forge_fact_flat "$2"
  _ff_key=$FORGE_FLAT
  shift 2
  FORGE_FACT=''
  _ff_rec=''
  if forge_facts_dir && [ -f "$FORGE_FACTS/$_ff_name.index" ]; then
    while IFS='	' read -r _ff_id _ff_k; do
      if [ "$_ff_k" = "$_ff_key" ]; then _ff_rec=$FORGE_FACTS/$_ff_name.$_ff_id; fi
    done < "$FORGE_FACTS/$_ff_name.index"
    if [ -n "$_ff_rec" ] && [ -f "$_ff_rec" ] && forge_fact_read "$_ff_rec"; then return 0; fi
  fi
  if [ -z "${FORGE_FACTS:-}" ] || ! [ -d "$FORGE_FACTS" ]; then
    _ff_out=$("$@") || return 1
    FORGE_FACT=$(printf '%s\n' "$_ff_out" | grep -v '^watch ')
    return 0
  fi
  _ff_new=$FORGE_FACTS/.$_ff_name.$$
  : > "$_ff_new.stamp"
  _ff_out=$("$@") || { rm -f "$_ff_new.stamp"; return 1; }
  # the record: its key, the paths it depends on (absent ones as such), its value
  _ff_keep=1
  {
    printf 'key\t%s\n' "$_ff_key"
    printf '%s\n' "$_ff_out" | while IFS= read -r _ff_l; do
      case $_ff_l in
        "watch "*)
          _ff_p=${_ff_l#watch }
          if [ -e "$_ff_p" ]; then printf 'watch\t%s\n' "$_ff_p"; else printf 'absent\t%s\n' "$_ff_p"; fi ;;
        *) printf 'value\t%s\n' "$_ff_l" ;;
      esac
    done
  } > "$_ff_new"
  # a path changed during the computation (or in the same clock tick): not kept
  while IFS='	' read -r _ff_t _ff_p; do
    # -nt is not in POSIX test, but in every shell Forge runs on (dash, bash, BusyBox ash; §9.4)
    # shellcheck disable=SC3013
    if [ "$_ff_t" = watch ] && ! [ "$_ff_new.stamp" -nt "$_ff_p" ]; then _ff_keep=0; fi
  done < "$_ff_new"
  FORGE_FACT=$(sed -n 's/^value	//p' "$_ff_new")
  if [ "$_ff_keep" = 1 ]; then
    _ff_id=$$
    # the records this one supersedes (the same key) go, the index keeps the 50 newest keys
    _ff_old=''
    if [ -f "$FORGE_FACTS/$_ff_name.index" ]; then
      while IFS='	' read -r _ff_i _ff_k; do
        if [ "$_ff_k" = "$_ff_key" ] && [ "$_ff_i" != "$_ff_id" ]; then _ff_old="$_ff_old $FORGE_FACTS/$_ff_name.$_ff_i"; fi
      done < "$FORGE_FACTS/$_ff_name.index"
    fi
    touch -r "$_ff_new.stamp" "$_ff_new" 2>/dev/null && mv -f "$_ff_new" "$FORGE_FACTS/$_ff_name.$_ff_id" \
      && { FORGE_FF_KEY=$_ff_key awk -F '\t' '$2 != ENVIRON["FORGE_FF_KEY"]' "$FORGE_FACTS/$_ff_name.index" 2>/dev/null | tail -n 49; printf '%s\t%s\n' "$_ff_id" "$_ff_key"; } > "$_ff_new.index" \
      && mv -f "$_ff_new.index" "$FORGE_FACTS/$_ff_name.index"
    # shellcheck disable=SC2086
    [ -z "$_ff_old" ] || rm -f $_ff_old
  fi
  rm -f "$_ff_new" "$_ff_new.stamp" "$_ff_new.index"
  return 0
}

# forge_fact_flat <text>: FORGE_FLAT, <text> on one line: backslashes doubled, newlines as
# \n and tabs as \t (one text, one flat form); builtins only.
forge_fact_flat() {
  FORGE_FLAT=''
  _fl_s=$1
  # a run of plain characters at a time, then the special one escaped
  while :; do
    _fl_p=${_fl_s%%[\\'
'	]*}
    FORGE_FLAT=$FORGE_FLAT$_fl_p
    [ "$_fl_p" != "$_fl_s" ] || return 0
    _fl_s=${_fl_s#"$_fl_p"}
    case $_fl_s in
      '\'*) FORGE_FLAT="$FORGE_FLAT\\\\" ;;
      '
'*) FORGE_FLAT="$FORGE_FLAT\\n" ;;
      *) FORGE_FLAT="$FORGE_FLAT\\t" ;;
    esac
    _fl_s=${_fl_s#?}
  done
}

# forge_fact_read <record>: sets FORGE_FACT from a record still valid (its key is
# $_ff_key, every watched path older than it, no absent one present); builtins only.
# shellcheck disable=SC3013
forge_fact_read() {
  _fr_v=''
  _fr_ok=0
  while IFS='	' read -r _fr_t _fr_x; do
    case $_fr_t in
      key) [ "$_fr_x" = "$_ff_key" ] && _fr_ok=1 ;;
      # not strictly older than the record: changed after it, or in the same clock tick (a shell comparing whole seconds)
      watch) [ "$1" -nt "$_fr_x" ] || return 1 ;;
      absent) [ -e "$_fr_x" ] && return 1 ;;
      value) _fr_v="${_fr_v:+$_fr_v
}$_fr_x" ;;
    esac
  done < "$1"
  [ "$_fr_ok" = 1 ] || return 1
  FORGE_FACT=$_fr_v
}

# forge_facts_dir: FORGE_FACTS, the facts' directory in this repository's state (created
# readable by the user only); fails outside a git repository.
forge_facts_dir() {
  if [ -z "${FORGE_FACTS:-}" ]; then
    if [ -n "${FORGE_STATE:-}" ]; then FORGE_FACTS=$FORGE_STATE/facts
    else
      _fd_top=$(git rev-parse --show-toplevel 2>/dev/null) && _fd_top=$(cd "$_fd_top" && pwd -P) || return 1
      FORGE_FACTS=$(forge_state_of "$_fd_top")/facts
    fi
  fi
  [ -d "$FORGE_FACTS" ] || (umask 077 && mkdir -p "$FORGE_FACTS") 2>/dev/null
}

# forge_pinned_ast_grep <args>: Forge's pinned ast-grep (forge_pinned: `forge_do ast-grep
# scan …`) through bunx (bun repos) or uvx, retried offline when uvx could not fetch it.
# Exit status: 0 no finding, 1 findings, 2 a usage error (its line on stderr), other = could
# not run.
forge_pinned_ast_grep() {
  if { [ -f bun.lock ] || [ -f bun.lockb ]; } && command -v bunx >/dev/null 2>&1; then
    astgrep_bunx "$@"
  elif forge_uvx_bin "ast-grep-cli==$FORGE_AST_GREP_VERSION" ast-grep; then
    # the binary uvx installed, run directly: uvx resolves the environment at every call
    "$FORGE_UVX_BIN" "$@"
  elif command -v uvx >/dev/null 2>&1; then
    _ag_err=${FORGE_TMP:-${TMPDIR:-/tmp}}/ag.err.$$
    uvx -q --from "ast-grep-cli==$FORGE_AST_GREP_VERSION" ast-grep "$@" 2> "$_ag_err"
    _rc=$?
    if [ "$_rc" -gt 1 ] && ! grep -q '^For more information, try' "$_ag_err"; then
      uvx -q --offline --from "ast-grep-cli==$FORGE_AST_GREP_VERSION" ast-grep "$@"
      _rc=$?
    else
      cat "$_ag_err" >&2
    fi
    rm -f "$_ag_err"
    return "$_rc"
  elif command -v bunx >/dev/null 2>&1; then
    astgrep_bunx "$@"
  else
    printf 'forge: bunx or uvx is needed to run ast-grep\n' >&2
    return 127
  fi
}

# astgrep_bunx <args>: `bunx -p <package> <bin>` installs the package again at every
# run (about a second); with --no-install it runs the copy in bunx's cache, which is
# installed first when it is not there (once per shell).
astgrep_bunx() {
  if [ -z "${_ag_bunx:-}" ]; then
    bunx --no-install -p "@ast-grep/cli@$FORGE_AST_GREP_VERSION" ast-grep --version >/dev/null 2>&1 \
      || bunx -p "@ast-grep/cli@$FORGE_AST_GREP_VERSION" ast-grep --version >/dev/null 2>&1
    _ag_bunx=1
  fi
  bunx --no-install -p "@ast-grep/cli@$FORGE_AST_GREP_VERSION" ast-grep "$@"
}

# forge_uvx_bin <requirement> <executable>: FORGE_UVX_BIN, the path of <executable> in the
# environment `uvx --from <requirement>` runs it from, kept as a fact while that file is
# there (uv may prune its cache: then it is asked again). Fails without uvx, or when uvx
# cannot install it (offline).
forge_uvx_bin() {
  FORGE_UVX_BIN=''
  forge_fact uvx-bin "$1 $2" forge_uvx_bin_ask "$1" "$2" || return 1
  if [ -z "$FORGE_FACT" ] || [ ! -x "$FORGE_FACT" ]; then
    # gone (uv pruned its cache): asked again
    [ -z "${FORGE_FACTS:-}" ] || rm -f "$FORGE_FACTS"/uvx-bin.*
    forge_fact uvx-bin "$1 $2" forge_uvx_bin_ask "$1" "$2" || return 1
    [ -n "$FORGE_FACT" ] && [ -x "$FORGE_FACT" ] || return 1
  fi
  FORGE_UVX_BIN=$FORGE_FACT
}

forge_uvx_bin_ask() {
  command -v uvx >/dev/null 2>&1 || return 1
  _ub=$(uvx -q --from "$1" python -c 'import shutil, sys; print(shutil.which(sys.argv[1]) or "")' "$2" 2>/dev/null) || return 1
  # kept while the file is there (forge_uvx_bin checks): it was just written, so its time cannot be watched
  case $_ub in /*) printf '%s\n' "$_ub" ;; *) return 1 ;; esac
}

# first_lines <n>: keep the first n lines of stdin (builtins).
first_lines() {
  _fl_n=0
  while [ "$_fl_n" -lt "$1" ] && { IFS= read -r _fl_l || [ -n "$_fl_l" ]; }; do
    printf '%s\n' "$_fl_l"
    _fl_n=$((_fl_n + 1))
    _fl_l=''
  done
}

# forge_dirname <path>: FORGE_DIR, the directory part of <path> ("." when none), as dirname; builtins.
forge_dirname() {
  case $1 in
    */*) FORGE_DIR=${1%/*}; [ -n "$FORGE_DIR" ] || FORGE_DIR=/ ;;
    *) FORGE_DIR=. ;;
  esac
}

# forge_cat <file>: prints <file> as it is, with shell builtins (text: a last line without
# its newline stays without it).
forge_cat() {
  _fc_l=''
  while IFS= read -r _fc_l; do printf '%s\n' "$_fc_l"; done < "$1"
  [ -z "$_fc_l" ] || printf '%s' "$_fc_l"
}

# repo_root: cd to the git repository containing the hook's cwd; sets FORGE_STATE. The
# repository is found by its .git (a directory, or a file for a worktree or submodule)
# from the cwd up, with builtins; git is asked only when none is found that way.
repo_root() {
  forge_json cwd
  [ -n "$FORGE_J" ] && cd "$FORGE_J" 2>/dev/null || return 1
  _rr_d=$(pwd -P 2>/dev/null) || _rr_d=$PWD
  while :; do
    if [ -e "$_rr_d/.git" ]; then break; fi
    case $_rr_d in /|'') _rr_d=''; break ;; esac
    _rr_d=${_rr_d%/*}
    [ -n "$_rr_d" ] || _rr_d=/
  done
  if [ -z "$_rr_d" ] || [ -n "${GIT_DIR:-}${GIT_WORK_TREE:-}" ]; then
    _rr_d=$(git rev-parse --show-toplevel 2>/dev/null) || return 1
  fi
  cd "$_rr_d" || return 1
  forge_state_of_cached "$(pwd -P)"
  FORGE_STATE=$FORGE_STATE_OF
}

# forge_state_of_cached <root>: FORGE_STATE_OF, forge_state_of's answer, kept in
# $FORGE_STATE_HOME/roots ("<root><TAB><state>" lines) so a hook does not hash the path.
forge_state_of_cached() {
  _sc_home=${FORGE_STATE_HOME:-$HOME/.claude/forge-state}
  FORGE_STATE_OF=''
  if [ -f "$_sc_home/roots" ]; then
    while IFS='	' read -r _sc_r _sc_s; do
      if [ "$_sc_r" = "$1" ]; then FORGE_STATE_OF=$_sc_s; return 0; fi
    done < "$_sc_home/roots"
  fi
  FORGE_STATE_OF=$(forge_state_of "$1")
  case $1 in *'	'*|*'
'*) return 0 ;; esac
  (umask 077 && mkdir -p "$_sc_home" && printf '%s\t%s\n' "$1" "$FORGE_STATE_OF" >> "$_sc_home/roots") 2>/dev/null
  return 0
}

# forge_state_of <repository root>: where the hooks keep this repository's state
# (turn snapshots, Stop results, the saved prompt, review verdicts, Bash snapshots):
# outside the repository, so that the agent's own Bash commands (sandboxed to the
# repository) cannot forge it: $FORGE_STATE_HOME (default ~/.claude/forge-state)
# /<first 16 hex of the sha256 of the root's physical path>.
forge_state_of() {
  printf '%s/%s' "${FORGE_STATE_HOME:-$HOME/.claude/forge-state}" "$(printf '%s' "$1" | forge_sha256 | cut -c 1-16)"
}

# forge_state_dir: creates $FORGE_STATE (readable by the user only); fails when it cannot.
forge_state_dir() {
  [ -n "${FORGE_STATE:-}" ] || return 1
  [ -d "$FORGE_STATE" ] || (umask 077 && mkdir -p "$FORGE_STATE") 2>/dev/null
}

# rel_path <path>: <path> relative to the current directory (the repository
# root after repo_root), resolving symlinks; fails when outside it.
rel_path() {
  case $1 in /*) _rp_p=$1 ;; *) forge_json cwd; _rp_p=$FORGE_J/$1 ;; esac
  forge_dirname "$_rp_p"
  _rp_d=$(cd "$FORGE_DIR" 2>/dev/null && pwd -P) || return 1
  _rp_root=$(pwd -P)
  case $_rp_d/ in "$_rp_root"/*) ;; *) return 1 ;; esac
  _rp_rel=${_rp_d#"$_rp_root"}
  _rp_rel=${_rp_rel#/}
  printf '%s' "${_rp_rel:+$_rp_rel/}${_rp_p##*/}"
}

# session_id: the hook input's session_id, safe as a file name ("default" if absent).
session_id() {
  forge_session
  printf '%s' "$FORGE_SESSION"
}

# forge_session: FORGE_SESSION, session_id's answer (builtins unless the id has other characters than A-Za-z0-9_-).
forge_session() {
  forge_json session_id
  case $FORGE_J in
    *[!A-Za-z0-9_-]*) FORGE_SESSION=$(printf '%s' "$FORGE_J" | tr -c 'A-Za-z0-9_-' '_') ;;
    *) FORGE_SESSION=$FORGE_J ;;
  esac
  [ -n "$FORGE_SESSION" ] || FORGE_SESSION=default
}

# forge_sha256: sha256 of stdin, hex (the digest's first field, read with builtins).
forge_sha256() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum
  elif command -v shasum >/dev/null 2>&1; then shasum -a 256
  else openssl dgst -sha256 -r
  fi | { IFS=' 	*' read -r _sh _; printf '%s\n' "$_sh"; }
}

# tree_hash [<head>]: hash of git diff HEAD plus the untracked files (names and contents;
# one git hash-object for all of them). <head>: HEAD's commit when the caller has it.
tree_hash() {
  {
    if [ -n "${1:-}" ] || git rev-parse --verify -q HEAD >/dev/null; then git diff HEAD --binary 2>/dev/null; else git diff --cached --binary 2>/dev/null; fi
    _th_u=$(git ls-files -z --others --exclude-standard 2>/dev/null | tr '\000' '\n')
    if [ -n "$_th_u" ]; then
      printf '%s\n' "$_th_u"
      printf '%s\n' "$_th_u" | git hash-object --stdin-paths 2>/dev/null
    fi
  } | forge_sha256
}

# status_paths: changed paths (staged, unstaged, untracked; renames as delete + add),
# one per line, as they are (-z: git quotes non-ASCII names otherwise); the status
# columns are cut with builtins.
status_paths() {
  git status --porcelain -z --no-renames --untracked-files=all 2>/dev/null | tr '\000' '\n' | while IFS= read -r _sp_l; do printf '%s\n' "${_sp_l#???}"; done
}

# snapshot <dir>: the working tree at the start of a turn, for the Stop hook:
# head (commit), tree (tree_hash), dirty ("path<TAB>blob hash", "-" when deleted)
# and files/<path> (copies of the dirty files up to 1 MiB, to compute added lines).
# The blob hashes and sizes are asked once for all the files (git hash-object
# --stdin-paths, wc -c), not per file.
snapshot() {
  rm -rf "$1" && mkdir -p "$1/files" || return 1
  git rev-parse -q --verify HEAD > "$1/head" 2>/dev/null || : > "$1/head"
  _sn_head=''
  read -r _sn_head < "$1/head"
  tree_hash "$_sn_head" > "$1/tree"
  status_paths > "$1/paths"
  : > "$1/present"
  while IFS= read -r _sn_f; do [ ! -f "$_sn_f" ] || printf '%s\n' "$_sn_f"; done < "$1/paths" > "$1/present"
  : > "$1/hashes"
  : > "$1/sizes"
  if [ -s "$1/present" ]; then
    git hash-object --stdin-paths < "$1/present" > "$1/hashes" 2>/dev/null
    # wc -c <files>: "<size> <path>" per file, then a total; the files in order
    (set -f; IFS='
'; # shellcheck disable=SC2046
      wc -c -- $(forge_cat "$1/present")) > "$1/sizes" 2>/dev/null
  fi
  exec 8< "$1/hashes" 9< "$1/sizes"
  while IFS= read -r _sn_f; do
    if [ -f "$_sn_f" ]; then
      _sn_h=''; _sn_z=''
      read -r _sn_h <&8
      IFS=' 	' read -r _sn_z _ <&9
      printf '%s\t%s\n' "$_sn_f" "$_sn_h"
      if [ "${_sn_z:-0}" -le 1048576 ] 2>/dev/null; then
        forge_dirname "$1/files/$_sn_f"
        { [ -d "$FORGE_DIR" ] || mkdir -p "$FORGE_DIR"; } && cp "$_sn_f" "$1/files/$_sn_f"
      fi
    else
      printf '%s\t-\n' "$_sn_f"
    fi
  done < "$1/paths" > "$1/dirty"
  exec 8<&- 9<&-
  rm -f "$1/paths" "$1/present" "$1/hashes" "$1/sizes"
}

# The base a change is measured against: FORGE_SNAP (a turn snapshot) and/or
# FORGE_BASE_REV (a commit). base_hash <path>: blob hash of <path> in the base, "-" if absent.
base_hash() {
  if [ -n "${FORGE_SNAP:-}" ] && _bh=$(awk -F '\t' -v p="$1" '$1 == p { print $2; f = 1; exit } END { exit !f }' "$FORGE_SNAP/dirty" 2>/dev/null); then
    printf '%s' "$_bh"
  elif [ -n "${FORGE_BASE_REV:-}" ] && _bh=$(git rev-parse -q --verify "$FORGE_BASE_REV:$1" 2>/dev/null); then
    printf '%s' "$_bh"
  else
    printf -- '-'
  fi
}

# now_hash <path>: blob hash of the working-tree file, "-" if absent.
now_hash() {
  if [ -f "$1" ]; then git hash-object -- "$1" 2>/dev/null; else printf -- '-'; fi
}

# base_file <path> <out>: writes <path> as it is in the base to <out>; fails if absent there.
# _bf_inrev=0 says <path> is not in FORGE_BASE_REV's tree (the caller looked it up).
base_file() {
  # the file was dirty at the turn's start: its snapshot copy ("-": it did not exist)
  _bf=''
  if [ -n "${FORGE_SNAP:-}" ] && [ -f "$FORGE_SNAP/dirty" ]; then
    while IFS='	' read -r _bf_p _bf_h; do
      if [ "$_bf_p" = "$1" ]; then _bf=${_bf_h:--}; break; fi
    done < "$FORGE_SNAP/dirty"
  fi
  if [ -n "$_bf" ]; then
    [ "$_bf" != - ] && [ -f "$FORGE_SNAP/files/$1" ] || return 1
    forge_dirname "$2"
    { [ -d "$FORGE_DIR" ] || mkdir -p "$FORGE_DIR"; } && cp "$FORGE_SNAP/files/$1" "$2"
  elif [ -n "${FORGE_BASE_REV:-}" ] && [ "${_bf_inrev:-1}" != 0 ]; then
    # one git process: the blob, or a failure when the path is not in the base
    forge_dirname "$2"
    { [ -d "$FORGE_DIR" ] || mkdir -p "$FORGE_DIR"; } || return 1
    git cat-file blob "$FORGE_BASE_REV:$1" > "$2" 2>/dev/null || { rm -f "$2"; return 1; }
  else
    return 1
  fi
}

# added_lines <path> <base-copy>: "path<TAB>line" for each line added since the base
# (git diff -U0: an edited line counts, moved code counts); "path<TAB>*" when
# <base-copy> does not exist (the file is new).
added_lines() {
  if [ ! -f "$2" ]; then printf '%s\t*\n' "$1"; return 0; fi
  # the hunk headers ("@@ -a,b +s,n @@"): lines s to s+n-1 (n absent: 1); one awk,
  # not a shell read loop (a long diff costs a read per line)
  git diff --no-index --no-ext-diff --no-textconv --no-color -U0 -- "$2" "$1" 2>/dev/null \
    | awk -v f="$1" '/^@@ / { split($3, p, ","); s = substr(p[1], 2) + 0; n = (p[2] == "" ? 1 : p[2] + 0); for (i = 0; i < n; i++) print f "\t" (s + i) }'
}

# turn_dir: the turn snapshot of this session (written by turn-start.sh).
turn_dir() {
  forge_session
  printf '%s/%s.turn' "$FORGE_STATE" "$FORGE_SESSION"
}

# ---- reviews of permission asks nobody can answer (review.sh)

# forge_review_wanted: succeeds when an ask should go to an independent reviewer:
# FORGE_ASK_REVIEW=always, or (auto, the default) a run with nobody to answer
# (CLAUDE_CODE_ENTRYPOINT sdk-cli, sdk-ts, sdk-py or claude-code-github-action:
# claude -p, the Agent SDK, the GitHub Action). Never inside a review, never with
# FORGE_ASK_REVIEW=never, never in dontAsk mode (the user chose to deny asks).
forge_review_wanted() {
  [ -z "${FORGE_REVIEWER:-}" ] || return 1
  case $FORGE_INPUT in *'"permission_mode":"dontAsk"'*|*'"permission_mode": "dontAsk"'*) return 1 ;; esac
  case ${FORGE_ASK_REVIEW:-auto} in
    always) return 0 ;;
    never) return 1 ;;
  esac
  case ${CLAUDE_CODE_ENTRYPOINT:-} in
    sdk-cli|sdk-ts|sdk-py|claude-code-github-action) return 0 ;;
  esac
  return 1
}

# forge_json_object <key>: the JSON value (object or array) of the first <key> in stdin.
forge_json_object() {
  awk -v key="$1" '
    { buf = buf $0 "\n" }
    END {
      if (!match(buf, "\"" key "\"[[:space:]]*:[[:space:]]*[{[]")) exit
      s = substr(buf, RSTART + RLENGTH - 1); n = length(s); depth = 0; str = 0
      for (i = 1; i <= n; i++) {
        c = substr(s, i, 1)
        if (str) { if (c == "\\") i++; else if (c == "\"") str = 0; continue }
        if (c == "\"") str = 1
        else if (c == "{" || c == "[") depth++
        else if (c == "}" || c == "]") { depth--; if (!depth) { print substr(s, 1, i); exit } }
      }
    }'
}

# forge_review <tool> <tool-input-json> [<rule> <concern> <question> [<request>]]: runs
# the reviewer, a fresh `claude -p` that sees only the action (tool, input, the
# repository path) and, for a rule's ask, that rule's concern and the one question
# to answer (and, when given, the user's request for the turn; never the
# conversation). It may read the repository (Read, Grep, Glob, nothing else) and
# runs without hooks, MCP servers or settings. Prints "allow<TAB>reason" or
# "deny<TAB>reason"; fails when claude is missing or gives no verdict (the ask then
# stays unanswered).
forge_review() {
  command -v claude >/dev/null 2>&1 || return 1
  if [ -n "${3:-}" ]; then
    _rv_concern=''
    [ -n "${4:-}" ] && _rv_concern=" The concern of that rule: $4"
    _rv_q=${5:-}
    [ -n "$_rv_q" ] || _rv_q='Is this action, as far as that concern goes, normal work on this repository and safe to run unattended?'
    _rv_req=''
    [ -n "${6:-}" ] && _rv_req="

The user's request for this turn (what the agent was asked to do; not the conversation):
<request>
$6
</request>"
    _rv_task="Forge flagged it with rule $3.$_rv_concern
The question you answer: $_rv_q$_rv_req

Judge only that question. The rest of the action is not under review: other commands or changes in it are covered by their own rules and permissions, and are no reason to deny. Allow when the answer clearly clears the concern; deny when it does not, or when you cannot tell."
  else
    _rv_task="Allow it only if it is clearly within normal work on this repository and safe to run unattended. Deny anything irreversible or destructive (deleting data or history, force pushes, dropping databases), anything that publishes, deploys or pushes outside this machine, anything that reads or sends secrets, installs packages you cannot verify, weakens security, permissions, tests or tool configuration, or runs code fetched from the internet. When in doubt, deny."
  fi
  _rv_prompt="You are reviewing one action that an autonomous coding agent wants to take. Nobody is available to approve it, so you decide in the user's place, as a careful senior developer who sees only this action would.

Repository: $(pwd)
Tool: $1
Input: $2

You do not see the agent's conversation or its reasons, on purpose: judge the action itself. You may read files in the repository to understand it. $_rv_task Give the reason in one sentence."
  _rv_schema='{"type":"object","properties":{"decision":{"type":"string","enum":["allow","deny"]},"reason":{"type":"string"}},"required":["decision","reason"],"additionalProperties":false}'
  _rv_out=$(FORGE_REVIEWER=1 claude -p "$_rv_prompt" --output-format json --json-schema "$_rv_schema" \
    --tools Read,Grep,Glob --allowedTools Read,Grep,Glob --permission-mode dontAsk --max-turns "${FORGE_REVIEW_MAX_TURNS:-12}" \
    --no-session-persistence --strict-mcp-config --setting-sources '' --settings '{"disableAllHooks":true}' \
    ${FORGE_REVIEW_MODEL:+--model "$FORGE_REVIEW_MODEL"} < /dev/null 2>/dev/null) || return 1
  _rv_so=${_rv_out#*'"structured_output":'}
  [ "$_rv_so" != "$_rv_out" ] || return 1
  _rv_d=$(FORGE_INPUT=$_rv_so json_get decision)
  _rv_r=$(FORGE_INPUT=$_rv_so json_get reason | tr '\t\n' '  ')
  case $_rv_d in allow|deny) printf '%s\t%s' "$_rv_d" "${_rv_r:-no reason given}" ;; *) return 1 ;; esac
}

# forge_review_state: where reviews are logged and cached: the repository's state
# directory (forge_state_of) in a Forge project, else ~/.claude.
forge_review_state() {
  if _rs_top=$(cd "$(json_get cwd)" 2>/dev/null && cd "$(git rev-parse --show-toplevel 2>/dev/null)" 2>/dev/null && pwd -P) \
    && [ -d "$_rs_top/.forge" ] && FORGE_STATE=$(forge_state_of "$_rs_top") && forge_state_dir; then
    printf '%s' "$FORGE_STATE"
  else
    printf '%s/.claude' "$HOME"
  fi
}

# forge_review_log <decision> <tool> <input> <reason>: one line per review in
# reviews.log in the state directory (in a Forge project) or ~/.claude/forge-reviews.log.
forge_review_log() {
  _rl_f=$(forge_review_state)
  case $_rl_f in "$HOME/.claude") _rl_f=$_rl_f/forge-reviews.log ;; *) _rl_f=$_rl_f/reviews.log ;; esac
  printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$(session_id)" "$1" "$2" "$(printf '%s' "$3" | tr '\t\n' '  ')" "$4" >> "$_rl_f" 2>/dev/null
  return 0
}

# forge_kill_tree <pid>: kills a process and its descendants.
# It is stopped first, so it cannot start a new child while its children are killed.
forge_kill_tree() {
  kill -STOP "$1" 2>/dev/null
  for _fk_c in $(ps -A -o pid= -o ppid= 2>/dev/null | awk -v p="$1" '$2 == p { print $1 }'); do
    forge_kill_tree "$_fk_c"
  done
  kill "$1" 2>/dev/null
  kill -CONT "$1" 2>/dev/null
}

# forge_kill_watch <pid>: stops a timeout watcher, "( sleep <n>; ... ) &" started by
# this shell, and its sleep.
# SIGKILL: a SIGTERM that reaches the subshell before it has dropped its parent's traps
# can be lost, and a watcher left alive holds the parent's saved descriptors (a hook's
# $(...) pipe) until its sleep ends. Stopped first, so it starts nothing meanwhile.
# forge_kill_watch <pid> [<file>]: the same; <file> holds the watcher's sleep pid (written
# by the watcher, "sleep <n> & echo $! > <file>; wait $!"), so no ps is needed.
forge_kill_watch() {
  kill -STOP "$1" 2>/dev/null
  _kw_c=''
  if [ -n "${2:-}" ] && [ -s "$2" ]; then read -r _kw_c < "$2"
  else _kw_c=$(ps -A -o pid= -o ppid= 2>/dev/null | awk -v p="$1" '$2 == p { print $1 }')
  fi
  # shellcheck disable=SC2086
  kill -9 "$1" $_kw_c 2>/dev/null
  # reaped here, so the shell does not report it ("Killed: 9") when it reaps a later job
  wait "$1" 2>/dev/null
  return 0
}

# ---- files changed by a Bash command (bash-snapshot.sh, post-edit.sh, typecheck.sh)

# bash_state: where Bash-command snapshots live; bash_key: this tool call's id, file-name safe.
bash_state() { printf '%s/bash' "$FORGE_STATE"; }
bash_key() {
  forge_json tool_use_id
  case $FORGE_J in
    '') return 1 ;;
    *[!A-Za-z0-9_-]*) printf '%s' "$FORGE_J" | tr -c 'A-Za-z0-9_-' '_' ;;
    *) printf '%s' "$FORGE_J" ;;
  esac
}

# tree_snapshot <seconds>: prints the git tree id of the working tree (tracked and
# untracked files, ignored ones left out) without touching the user's index or
# object store: a copy of .git/index, and new blobs written under bash_state/objects
# (the repository's objects are read as alternates). Fails after <seconds>.
tree_snapshot() {
  _ts_s=$FORGE_STATE/bash
  [ -d "$_ts_s/objects" ] || mkdir -p "$_ts_s/objects" || return 1
  _ts_objs=$(cd "$_ts_s/objects" && pwd -P) || return 1
  # the repository's object directory and index, in one git call
  _ts_p=$(git rev-parse --git-path objects --git-path index 2>/dev/null) || return 1
  _ts_alt=$(cd "${_ts_p%%
*}" 2>/dev/null && pwd -P) || return 1
  _ts_idx=${_ts_p#*
}
  _ts_tmp=$_ts_s/index.$$
  if [ -f "$_ts_idx" ]; then cp "$_ts_idx" "$_ts_tmp"; elif [ -e "$_ts_tmp" ]; then rm -f "$_ts_tmp"; fi
  (
    export GIT_INDEX_FILE="$_ts_tmp" GIT_OBJECT_DIRECTORY="$_ts_objs" GIT_ALTERNATE_OBJECT_DIRECTORIES="$_ts_alt"
    git add -A . >/dev/null 2>&1 && git write-tree 2>/dev/null
  ) > "$_ts_tmp.out" &
  _ts_pid=$!
  ( sleep "$1" & printf '%s\n' "$!" > "$_ts_tmp.sleep"; wait "$!"; forge_kill_tree "$_ts_pid" ) >/dev/null 2>&1 &
  _ts_watch=$!
  wait "$_ts_pid" 2>/dev/null
  _ts_rc=$?
  forge_kill_watch "$_ts_watch" "$_ts_tmp.sleep"
  _ts_tree=''
  read -r _ts_tree 2>/dev/null < "$_ts_tmp.out"
  rm -f "$_ts_tmp" "$_ts_tmp.out" "$_ts_tmp.lock" "$_ts_tmp.sleep"
  [ "$_ts_rc" -eq 0 ] && [ -n "$_ts_tree" ] || return 1
  printf '%s\n' "$_ts_tree"
}

# bash_changed_files <before-tree> <after-tree>: added or modified files, one per
# line, outside Forge's, Claude's, git's and dependency directories.
bash_changed_files() {
  _bc_objs=$(cd "$FORGE_STATE/bash/objects" && pwd -P) || return 1
  _bc_alt=$(cd "$(git rev-parse --git-path objects 2>/dev/null)" 2>/dev/null && pwd -P) || return 1
  GIT_OBJECT_DIRECTORY="$_bc_objs" GIT_ALTERNATE_OBJECT_DIRECTORIES="$_bc_alt" \
    git diff-tree -r --no-renames --name-status "$1" "$2" 2>/dev/null \
    | awk -F '\t' '$1 == "A" || $1 == "M" { print $2 }' \
    | grep -vE '^(\.forge|\.claude|\.git|node_modules|\.venv)/' 
  return 0
}

# bash_cleanup [age]: drops the snapshots beyond the 50 newest (a denied command never
# reaches PostToolUse), with "age" (once per session: session-start.sh) also those older
# than a day, and the snapshot objects once none is pending. Counted with builtins: ls, find
# and rm run only when there is something to drop.
bash_cleanup() {
  _bl_s=$FORGE_STATE/bash
  [ -d "$_bl_s" ] || return 0
  bash_count
  if [ "${1:-}" = age ] && [ "$_bl_n" -gt 0 ]; then
    find "$_bl_s" -type f \( -name '*.tree' -o -name '*.files' \) -mtime +0 -exec rm -f {} + 2>/dev/null
    bash_count
  fi
  if [ "$_bl_n" -gt 50 ]; then
    # shellcheck disable=SC2012
    ls -t "$_bl_s" 2>/dev/null | grep -E '\.(tree|files)$' | sed '1,50d' | while IFS= read -r _bl_f; do rm -f "$_bl_s/$_bl_f"; done
    bash_count
  fi
  if [ "$_bl_t" = 0 ] && [ -d "$_bl_s/objects" ]; then rm -rf "$_bl_s/objects"; fi
  return 0
}

# bash_count: _bl_n, the snapshots and change lists in $_bl_s; _bl_t, the snapshots (builtins).
bash_count() {
  _bl_n=0 _bl_t=0
  for _bl_f in "$_bl_s"/*.tree "$_bl_s"/*.files; do
    [ -e "$_bl_f" ] || continue
    _bl_n=$((_bl_n + 1))
    case $_bl_f in *.tree) _bl_t=$((_bl_t + 1)) ;; esac
  done
}

# ---- engine capabilities (SPECS §15): the types engine, one daemon per language and
# repository in $FORGE_STATE/types/<lang>/ (in: the request FIFO; pid, ready, want,
# log; sessions/ holds one file per Claude Code session using it).

# forge_types_alive <lang>: its daemon is running.
forge_types_alive() {
  [ -p "$FORGE_STATE/types/$1/in" ] && [ -f "$FORGE_STATE/types/$1/ready" ] || return 1
  _ta_pid=''
  read -r _ta_pid 2>/dev/null < "$FORGE_STATE/types/$1/pid"
  [ -n "$_ta_pid" ] && kill -0 "$_ta_pid" 2>/dev/null
}

# forge_types_line <lang> <line>: writes one line (shorter than PIPE_BUF, so writers
# never mix) to the daemon's FIFO. Opened read-write, so it never blocks.
forge_types_line() { printf '%s\n' "$2" 1<>"$FORGE_STATE/types/$1/in"; }

# forge_types_ask <lang> <dir> [stop]: asks the daemon the question in <dir>/req and
# prints its answer (without the final "end"); with "stop", asks it to stop and waits
# until it has (its language server ended). Fails when no answer comes within
# FORGE_TYPES_TIMEOUT seconds (20). The reply FIFO is opened read-write before the
# question is sent, so the daemon's non-blocking open always finds a reader.
forge_types_ask() {
  mkfifo "$2/reply" || return 1
  exec 8<>"$2/reply"
  forge_types_line "$1" "${3:+$3	}$2"
  { sleep "${FORGE_TYPES_TIMEOUT:-20}" & printf '%s\n' "$!" > "$2/sleep"; wait "$!"
    printf 'error\tno answer within %ss\nend\n' "${FORGE_TYPES_TIMEOUT:-20}" 1<>"$2/reply"; } >/dev/null 2>&1 &
  _ta_w=$!
  _ta_rc=1
  while IFS= read -r _ta_l <&8; do
    [ "$_ta_l" = end ] && { _ta_rc=0; break; }
    printf '%s\n' "$_ta_l"
  done
  forge_types_unwatch "$_ta_w" "$2/sleep"
  exec 8<&-
  return "$_ta_rc"
}

# forge_types_unwatch <watchdog pid> <file with its sleep's pid>: ends a watchdog by
# its sleep, so the watchdog ends on its own (killing it would make some shells print
# "Terminated"); its late line goes to a FIFO nobody reads any more.
forge_types_unwatch() {
  _tw_n=0
  while [ ! -s "$2" ] && [ "$_tw_n" -lt 100 ]; do _tw_n=$((_tw_n + 1)); done
  if [ -s "$2" ] && read -r _tw_p < "$2"; then kill "$_tw_p" 2>/dev/null; else kill "$1" 2>/dev/null; fi
  wait "$1" 2>/dev/null
  return 0
}

# forge_types_changed <path>...: tells the running daemons that files changed on disk
# (they resync them). A dependency or configuration change restarts them instead: the
# next question starts them again on the new environment.
forge_types_changed() {
  [ -d "$FORGE_STATE/types" ] || return 0
  for _tc_lang in python typescript; do
    forge_types_alive "$_tc_lang" || continue
    for _tc_f in "$@"; do
      case $_tc_f in
        uv.lock|*/uv.lock|pyproject.toml|*/pyproject.toml|ty.toml|bun.lock|bun.lockb|package-lock.json|pnpm-lock.yaml|yarn.lock|package.json|*/package.json|tsconfig*.json|*/tsconfig*.json)
          forge_types_line "$_tc_lang" restart; break ;;
        *) forge_types_line "$_tc_lang" "changed	$_tc_f" ;;
      esac
    done
  done
}

# forge_types_stop <lang>: stops the language's daemon and waits until it and its
# language server have exited (at most FORGE_TYPES_TIMEOUT seconds).
forge_types_stop() {
  forge_types_alive "$1" || return 0
  _tp_r=$(mktemp -d "${TMPDIR:-/tmp}/forge-types-stop.XXXXXX") || return 1
  forge_types_ask "$1" "$_tp_r" stop > /dev/null
  rm -rf "$_tp_r"
  return 0
}

# forge_types_session <start|end>: registers this Claude Code session with the running
# daemons, or unregisters it; the last session to end stops them.
forge_types_session() {
  for _tx_lang in python typescript; do
    _tx_d=$FORGE_STATE/types/$_tx_lang
    [ -d "$_tx_d" ] || continue
    if [ "$1" = start ]; then mkdir -p "$_tx_d/sessions" && : > "$_tx_d/sessions/$(session_id)"
    else
      rm -f "$_tx_d/sessions/$(session_id)"
      [ -n "$(ls "$_tx_d/sessions" 2>/dev/null)" ] || forge_types_stop "$_tx_lang"
    fi
  done
  return 0
}
